pub fn config(&self, inputs: &[Input]) -> Result<Config> {
    let style_components = self.style_components()?;

    let paging_mode = match self.matches.get_one::<String>("paging").map(|s| s.as_str()) {
        Some("always") => PagingMode::Always,
        Some("never") => PagingMode::Never,
        Some("auto") | None => {
            // If we have -pp as an option when in auto mode, the pager should be disabled.
            let extra_plain = self.matches.get_count("plain") > 1;
            if extra_plain || self.matches.get_flag("no-paging") {
                PagingMode::Never
            } else if inputs.iter().any(Input::is_stdin) {
                // If we are reading from stdin, only enable paging if we write to an
                // interactive terminal and if we do not *read* from an interactive
                // terminal.
                if self.interactive_output && !std::io::stdin().is_terminal() {
                    PagingMode::QuitIfOneScreen
                } else {
                    PagingMode::Never
                }
            } else if self.interactive_output {
                PagingMode::QuitIfOneScreen
            } else {
                PagingMode::Never
            }
        }
        _ => unreachable!("other values for --paging are not allowed"),
    };

    let syntax_mapping = self.syntax_mapping_from_matches()?;
    let maybe_term_width = self.terminal_width_from_matches();

    Ok(Config {
        true_color: Self::is_truecolor_terminal(),
        language: self.language_from_matches(),
        show_nonprintable: self.matches.get_flag("show-all"),
        nonprintable_notation: self.nonprintable_notation_from_matches(),
        binary: self.binary_behavior_from_matches(),
        wrapping_mode: self.wrapping_mode_from_matches(&style_components, maybe_term_width),
        colored_output: self.colored_output_from_matches(),
        paging_mode,
        term_width: maybe_term_width.unwrap_or(Term::stdout().size().1 as usize),
        loop_through: self.loop_through_from_matches(),
        tab_width: self.tab_width_from_matches(&style_components, paging_mode),
        strip_ansi: self.strip_ansi_from_matches(),
        theme: self.theme_from_matches(),
        visible_lines: self.visible_lines_from_matches()?,
        style_components,
        syntax_mapping,
        pager: self.pager_from_matches(),
        use_italic_text: self.italic_text_from_matches(),
        highlighted_lines: self.highlighted_lines_from_matches()?,
        use_custom_assets: self.custom_assets_from_matches(),
        #[cfg(feature = "lessopen")]
        use_lessopen: self.matches.get_flag("lessopen"),
        set_terminal_title: self.terminal_title_from_matches(),
        squeeze_lines: self.squeeze_lines_from_matches(),
    })
}

