let mut paging_mode = match self.matches.get_one::<String>("paging").map(|s| s.as_str()) {
    Some("always") => PagingMode::Always,
    Some("never") => PagingMode::Never,
    Some("auto") | None => {
        if inputs.iter().any(Input::is_stdin) {
            // If we are reading from stdin, only enable paging if we write to an
            // interactive terminal and if we do not *read* from an interactive
            // terminal.
            if self.interactive_output && !std::io::stdin().is_terminal() {
                PagingMode::QuitIfOneScreen
            } else {
                PagingMode::Never
            }
        } else if self.interactive_output {
            PagingMode::QuitIfOneScreen
        } else {
            PagingMode::Never
        }
    }
    _ => unreachable!("other values for --paging are not allowed"),
};

// Both '-pp' and '--no-paging' (or '-P') disable paging, but only if they
// are not overridden by a later explicit '--paging' option.
let extra_plain = self.matches.get_count("plain") > 1;
let no_paging = self.matches.get_flag("no-paging");
if extra_plain || no_paging {
    let paging_index = self
        .matches
        .value_source("paging")
        .filter(|source| *source != ValueSource::DefaultValue)
        .and_then(|_| self.matches.index_of("paging"));
    let disable_index = [
        extra_plain
            .then(|| self.matches.index_of("plain"))
            .flatten(),
        no_paging
            .then(|| self.matches.index_of("no-paging"))
            .flatten(),
    ]
    .into_iter()
    .flatten()
    .max();

    if !matches!((paging_index, disable_index), (Some(p), Some(d)) if p > d) {
        paging_mode = PagingMode::Never;
    }
}

